  const t = todo('Việc tốt');
  const bad = {
    'unknown field': { ...todo('a'), x: 1 },
    'missing field': { id: 'z', title: 'a', done: false },
    'proto key': JSON.parse('{"id": "p", "title": "a", "done": false, "createdAt": 1, "__proto__": {}}'),
    'empty id': todo('a', { id: '' }),
    'id not a string': todo('a', { id: 7 }),
    'empty title': todo(''),
    'blank title': todo('   '),
